function showToast(message = 'Message sent successfully') { const toast = document.getElementById('toast'); const toastMsg = document.getElementById('toastMsg'); if (!toast || !toastMsg) { return; } toastMsg.textContent = message; toast.classList.add('show'); window.clearTimeout(showToast.timeoutId); showToast.timeoutId = window.setTimeout(() => { toast.classList.remove('show'); }, 3000); } function resetForm() { const form = document.getElementById('contactForm'); const formContent = document.getElementById('formContent'); const formSuccess = document.getElementById('formSuccess'); const submitButton = document.querySelector('.submit-btn'); if (form) { form.reset(); } if (formContent) { formContent.style.display = 'block'; } if (formSuccess) { formSuccess.style.display = 'none'; } if (submitButton) { submitButton.disabled = false; submitButton.textContent = 'Send Message →'; } } function submitForm(event) { event.preventDefault(); const firstName = document.getElementById('firstName').value.trim(); const lastName = document.getElementById('lastName').value.trim(); const email = document.getElementById('email').value.trim(); const phone = document.getElementById('phone').value.trim(); const projectType = document.getElementById('projectType').value; const message = document.getElementById('message').value.trim(); const formButton = event.submitter || document.querySelector('.submit-btn'); if (!firstName || !lastName || !email || !phone || !projectType || !message) { showToast('Please fill in all fields'); return; } const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/; if (!emailRegex.test(email)) { showToast('Please enter a valid email address'); return; } formButton.disabled = true; formButton.textContent = 'Sending...'; fetch('/', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams(new FormData(event.target)).toString(), }).then(() => { document.getElementById('formContent').style.display = 'none'; document.getElementById('formSuccess').style.display = 'block'; showToast('Your message has been sent successfully!'); window.setTimeout(() => { resetForm(); }, 3000); }).catch(() => { formButton.disabled = false; formButton.textContent = 'Send Message →'; showToast('Something went wrong. Please try again.'); }); } document.addEventListener('DOMContentLoaded', () => { const hashLinks = document.querySelectorAll('a[href^="#"]'); const scrollTopBtn = document.getElementById('scrollTopBtn'); const form = document.getElementById('contactForm'); const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches; hashLinks.forEach((link) => { link.addEventListener('click', (event) => { const href = link.getAttribute('href'); if (!href || href === '#') { event.preventDefault(); window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' }); return; } const targetElement = document.querySelector(href); if (!targetElement) { return; } event.preventDefault(); const offsetTop = targetElement.getBoundingClientRect().top + window.scrollY - 88; window.scrollTo({ top: offsetTop, behavior: reduceMotion ? 'auto' : 'smooth' }); }); }); if (form) { form.addEventListener('submit', submitForm); } if (scrollTopBtn) { const toggleScrollTop = () => { const shouldShow = window.scrollY > 420; scrollTopBtn.classList.toggle('is-visible', shouldShow); }; toggleScrollTop(); window.addEventListener('scroll', toggleScrollTop, { passive: true }); scrollTopBtn.addEventListener('click', () => { window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' }); }); } const revealTargets = document.querySelectorAll( 'section, .service-card, .why-card, .portfolio-card, .testimonial-card, .about-skills, .about-stats, .contact-item, .contact-form' ); if (reduceMotion) { revealTargets.forEach((element) => element.classList.add('is-visible')); return; } const revealObserver = new IntersectionObserver( (entries, observer) => { entries.forEach((entry) => { if (!entry.isIntersecting) { return; } entry.target.classList.add('is-visible'); observer.unobserve(entry.target); }); }, { threshold: 0.16, rootMargin: '0px 0px -8% 0px' } ); revealTargets.forEach((element) => { element.classList.add('reveal-item'); revealObserver.observe(element); }); });
